package com.clearinghouse.batch.controller;

import org.springframework.batch.core.JobExecution;
import org.springframework.batch.core.explore.JobExplorer;
import org.springframework.batch.core.launch.JobOperator;
import org.springframework.http.ResponseEntity;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/batch/settlement")
public class BatchJobExecutionController {

    private final JobOperator jobOperator;
    private final JobExplorer jobExplorer;

    public BatchJobExecutionController(JobOperator jobOperator, JobExplorer jobExplorer) {
        this.jobOperator = jobOperator;
        this.jobExplorer = jobExplorer;
    }

    @PostMapping("/executions/{jobExecutionId}/restart")
    public ResponseEntity<String> restartSettlementJob(
            @PathVariable Long jobExecutionId,
            Authentication authentication) throws Exception {
        JobExecution jobExecution = jobExplorer.getJobExecution(jobExecutionId);
        if (jobExecution == null) {
            return ResponseEntity.notFound().build();
        }
        String merchantIdParam = jobExecution.getJobParameters().getString("merchantId");
        if (merchantIdParam == null || !merchantIdParam.equals(authentication.getName())) {
            throw new AccessDeniedException("Merchant not authorized to restart batch job execution " + jobExecutionId);
        }
        Long newExecutionId = jobOperator.restart(jobExecutionId);
        return ResponseEntity.ok("Settlement job restarted with execution ID: " + newExecutionId);
    }
}
